#!/usr/bin/env node
/**
 * Refreshes `src/types/api.d.ts` from a backend checkout.
 *
 *   npm run types:api
 *   TALIM_BACKEND_PATH=/path/to/talimBE-V2 npm run types:api
 *
 * No network: it copies `<backend>/docs/api-types.d.ts` (generated by the
 * backend's `npm run openapi:types`). When the backend is not checked out it
 * says so and exits 0, so it is safe in scripts and CI.
 */
import { copyFileSync, existsSync, mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * Copies the generated contract into the app.
 *
 * @param {{ source: string, target: string }} paths - Absolute or cwd-relative file paths.
 * @returns {{ status: 'missing-source' | 'unchanged' | 'created' | 'updated', source: string, target: string }}
 *   What happened. `missing-source` means nothing was written.
 */
export function syncApiTypes({ source, target }) {
  if (!existsSync(source)) return { status: 'missing-source', source, target };

  const next = readFileSync(source);
  const existed = existsSync(target);
  if (existed && readFileSync(target).equals(next)) return { status: 'unchanged', source, target };

  mkdirSync(dirname(target), { recursive: true });
  copyFileSync(source, target);
  return { status: existed ? 'updated' : 'created', source, target };
}

/** Runs the sync against the conventional locations and reports the outcome. */
function main() {
  const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
  const backend = resolve(root, process.env.TALIM_BACKEND_PATH ?? '../talimBE-V2');
  const result = syncApiTypes({
    source: resolve(backend, 'docs/api-types.d.ts'),
    target: resolve(root, 'src/types/api.d.ts'),
  });

  if (result.status === 'missing-source') {
    console.log(
      `Backend contract not found at ${result.source}. ` +
        'Check out talimBE-V2 next to this repo or set TALIM_BACKEND_PATH. Nothing changed.',
    );
  } else if (result.status === 'unchanged') {
    console.log('src/types/api.d.ts is already up to date.');
  } else {
    console.log(`src/types/api.d.ts ${result.status} from ${result.source}. Run npm run typecheck.`);
  }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
